/**
 * The world source that asks the engine, and draws the answers it gets back.
 *
 * This is where the two halves of the product meet. The canvas was written
 * against `WorldSource` and nothing else, so joining it to the engine changed no
 * component: the object handed in changed, the slots that used to read *no
 * engine yet* now hold computed numbers, and every absence that is still on
 * screen is still an absence for a reason it can name.
 *
 * **Three questions, three routes, and nothing else is asked.**
 *
 * | The question | Where it is asked |
 * |---|---|
 * | What does this branch make the map say? | `POST /api/worlds` |
 * | What moved between the map as written and the map with my edits? | `POST /api/worlds/diff` |
 * | What is the number on this one arrow? | `POST /api/worlds/conditional` |
 *
 * A fourth thing is read and is not the engine's: the map itself — the claims,
 * their wording, how each is judged, the arrows and what is cited for them —
 * which comes from the stored-example route. A map is written by hand; a world
 * never is. So the map is read once and kept, and the engine is asked again
 * every time an edit lands.
 *
 * **There is no arithmetic on a likelihood anywhere in this file.** Numbers
 * arrive from the engine and are carried, untouched and at full precision, to
 * the moment they are printed. Which way a claim moved is read off the sign of
 * the engine's own difference — a comparison, not a subtraction — and no two
 * numbers on this map are ever combined here.
 *
 * **Nothing here is invented.** A branch that does not fit comes back as every
 * reason at once and is thrown on for the screen to print. A claim under a live
 * supposition gets the word rather than the `1` the engine stores for it. And a
 * chain's multiplied-out likelihood, which the engine does not carry, stays an
 * absence that says exactly that rather than being worked out here.
 */

import type { ClaimDiff, Diff, World } from "../api/client";
import { readConditional, readDiff, readExample, readWorld } from "../api/client";
import { ADDED, happened, retracted, supposed } from "../graph/diff/badges";
import { daysApart } from "../graph/diff/days";
import { NO_CHANGE, noChangeReason } from "../graph/diff/noChange";
import { inTheEnginesWords, noReadingAtAll } from "./absence";
import { filled, NO_PATH_PRODUCT, seedFor, toClaim, toLink } from "./fromTheServer";
import { NOT_ON_THIS_MAP } from "./naming";
import type { FixtureBundle, WorldSource } from "./source";
import type {
  Badge,
  BranchView,
  ClaimChange,
  ClaimView,
  ConditionalRequest,
  DeltaRow,
  DiffRequest,
  DiffView,
  Known,
  Movement,
  Ranged,
  Standing,
  WireBranch,
  WorldRequest,
  WorldView,
} from "./types";

/**
 * Which likelihood on a claim's series is the one its tile shows.
 *
 * A tile's headline number is read on the claim's **own resolve-by day** — the
 * day the claim is judged, which every claim has and which the tile already
 * prints. So the word beside that number has to be read on the same day, or the
 * tile would say *Supposed* over a number worked out for a different morning.
 *
 * **This is the engine's own rule, written again.** `_read_on` in
 * `backend/src/katalyst/domain/diff.py` pins the day inside the window, then
 * takes the first drawn day at or after it, and never falls off the end. The
 * browser asked for an exact match instead, so a claim judged on a day the
 * series does not carry — a window longer than 180 days is drawn at fewer
 * points, and a claim added on a branch brings its own resolve-by day — got no
 * word beside its number at all, while the engine happily read one. Two rules
 * for *which day is this claim's day* is one too many, so this is that one.
 *
 * @param world The world as the engine built it.
 * @param resolvesBy The claim's own resolve-by day.
 * @returns Where that day sits among the days the world was worked through, or
 *   nothing at all when the date cannot be read or the world drew no days.
 */
function whereItsDaySits(world: World, resolvesBy: string): number | null {
  const offset = daysApart(world.day_zero, resolvesBy);
  const drawn = world.series_days;
  if (offset === null || drawn.length === 0) {
    return null;
  }
  // Inside the window first — a claim judged before day zero is read on day
  // zero, and one judged after the last day is read on the last day.
  const wanted = Math.min(Math.max(0, offset), world.days);
  const at = drawn.findIndex((day) => day >= wanted);
  return at === -1 ? drawn.length - 1 : at;
}

/**
 * What a tile says about the edits behind it, read off the world rather than
 * worked out from the branch.
 *
 * The world carries both halves: every value an edit fixed, in the order the
 * edits were made, and every supposition a later edit undermined with the day
 * and the arrow that did it. Reading the badges off those is what closes the
 * question the diff chapter left open — two derivations of one line eventually
 * disagree, so there is one, and it is the world's.
 *
 * One badge is not on the world and cannot be: **Added**. Whether a claim
 * arrived with an edit is a fact about the branch, and the branch is what says
 * so — the world only shows the map the edits left behind, in which an added
 * claim looks like any other.
 *
 * @param world The world as the engine built it.
 * @param words Every claim's own words, so a badge can quote one.
 * @param added The claims this branch brought with it.
 * @returns One list of badges per claim that has any, in the order they were
 *   earned.
 */
function badgesFromTheWorld(
  world: World,
  words: ReadonlyMap<string, string>,
  added: ReadonlySet<string>,
): Map<string, Badge[]> {
  const badges = new Map<string, Badge[]>();
  const add = (claim: string, badge: Badge): void => {
    badges.set(claim, [...(badges.get(claim) ?? []), badge]);
  };

  // A claim an edit brought with it earns **Added** before anything it is later
  // supposed to be: it has to be on the map before anything can be said about
  // it, so that is the order the two badges read in.
  for (const claim of added) {
    add(claim, ADDED);
  }

  const supposedOn = new Map<string, string>();
  for (const fixed of world.assignments) {
    const day = fixed.at ?? world.day_zero;
    if (fixed.kind === "do") {
      add(fixed.target, supposed(day, fixed.value));
      if (fixed.value) {
        supposedOn.set(fixed.target, day);
      }
    } else {
      add(fixed.target, happened(day, fixed.value));
    }
  }

  for (const end of world.retractions) {
    const cause = words.get(end.by_claim) ?? end.by_claim;
    add(end.target, retracted(end.at, cause, supposedOn.get(end.target) ?? end.at));
  }

  return badges;
}

/**
 * Which claims an edit has fixed the value of, on their own judging day.
 *
 * **One rule, and it is not a rule about suppositions.** A claim whose value an
 * edit fixed is true — or false — in every version of the map, so the engine
 * stores a flat `1` or `0` for it, and **no surface but the path product prints
 * that number.** Every other reader writes the word where the likelihood would
 * go: *Supposed · Oct 1* where the reader took it as given, *Happened · Oct 1*
 * where they reported it as news. Answering either with a likelihood is a tool
 * arguing with the person using it — and `>.99` is that number wearing the
 * certainty guard's clothes.
 *
 * **The two are found in different places, and that is the engine's shape rather
 * than ours.** A supposition can be undermined by a later edit, so whether it
 * still holds is a fact about a *day*, and the world's `states` carry it — H
 * reads *supposed* on the first and *pushed* by the day it is judged. An
 * observation is news: nothing takes it back, it holds across the whole window,
 * and the world records it as an assignment rather than as a state.
 *
 * @param world The world as the engine built it.
 * @param claims The claims, so each one's resolve-by day can be found.
 * @param badges The badges, for the words and the sentence behind them.
 */
function standingFromTheWorld(
  world: World,
  claims: readonly ClaimView[],
  badges: ReadonlyMap<string, readonly Badge[]>,
): Map<string, Standing> {
  // What each observed claim was reported to be, so the word beside it is the
  // one the engine was actually told rather than the one the button says.
  const observed = new Map(
    world.assignments
      .filter((fixed) => fixed.kind === "observe")
      .map((fixed) => [fixed.target, fixed.value] as const),
  );
  const standing = new Map<string, Standing>();
  for (const claim of claims) {
    const at = whereItsDaySits(world, claim.resolvesBy);
    const isSupposed = at !== null && world.states[claim.id]?.[at] === "supposed";
    const isNews = observed.has(claim.id);
    if (!isSupposed && !isNews) {
      continue;
    }
    const word = isSupposed ? "Supposed" : observed.get(claim.id) ? "Happened" : "Did not happen";
    const said = (badges.get(claim.id) ?? []).find((badge) => badge.words.startsWith(word));
    standing.set(claim.id, {
      words: said?.words ?? word,
      reason:
        `${said?.reason ?? "An edit fixed this claim's value."} It is settled in every version ` +
        `of the map, so there is no likelihood to show.`,
    });
  }
  return standing;
}

/**
 * The one sentence under a computed map, saying where every number on it came
 * from.
 *
 * It names both halves — the address the map was read from and the address its
 * likelihoods were worked out at — and the three things anyone would need to
 * rebuild the same answer: the map, the branch, and the seed.
 */
function originOf(world: World, bundle: FixtureBundle, branchLabel: string | null): string {
  const which =
    branchLabel === null
      ? "with nothing done to it"
      : `with the branch "${branchLabel}" folded onto it`;
  return (
    `Every claim, arrow and date came from /api/fixtures/${bundle.id}; every likelihood was ` +
    `worked out by /api/worlds from that map ${which}, at seed ${world.seed}, over ` +
    `${world.versions.toLocaleString("en-GB").replace(/,/g, " ")} versions of the map with ` +
    `${world.worlds} worlds under each. Nothing here was typed in: the same map, branch and ` +
    `seed give the same answer every time.`
  );
}

/**
 * The four things about a map that a computed world does not carry.
 *
 * A world knows its own numbers and the map the edits left behind; it does not
 * know what that map is called on screen, where it was read from, or the sentence
 * that says where its numbers came from. Those come from whoever asked — the
 * stored-example route here, a generation's own stream in `src/stream/growth.ts`
 * — which is what lets **one** function turn a world into what the canvas draws.
 * Two such functions would drift inside a week, and then a generated map and a
 * fetched map would disagree about a number neither of them computed.
 */
export interface WorldSummary {
  /** What this map is asked for by, such as `hormuz`, or a generation's own name. */
  readonly id: string;
  /** What the map is called on screen. */
  readonly title: string;
  /** The day the map is set on, as the map writes a day: `2026-10-01`. */
  readonly day: string;
  /** One sentence under the map saying where every number on it came from. */
  readonly origin: string;
}

/**
 * Turn one computed world into the world the canvas draws.
 *
 * **This is the only function that does it.** Both callers — the stored-example
 * source below and the reducer that folds a generation's stream — hand their
 * world through here, so a map that was fetched and a map that was watched being
 * built cannot say different things about the same claim.
 *
 * @param world The world as the engine built it.
 * @param from What this map is called and where it came from.
 * @param branch The branch that was folded, or nothing on the base world.
 */
export function toWorldView(world: World, from: WorldSummary, branch?: BranchView): WorldView {
  // The map the engine's edits left behind, which is the map to draw: a branch
  // that added a claim added it here too.
  const claims = world.graph.propositions.map(toClaim);
  const words = new Map(claims.map((claim) => [claim.id, claim.claim]));
  const added = new Set(
    (branch?.edits ?? []).flatMap((edit) => (edit.op === "insert" ? [edit.claimId] : [])),
  );
  const badges = badgesFromTheWorld(world, words, added);
  const standing = standingFromTheWorld(world, claims, badges);

  return {
    baseId: from.id,
    title: from.title,
    today: from.day,
    hypothesisId: world.graph.hypothesis_id,
    claims: claims.map((claim): ClaimView => {
      const computed = world.beliefs[claim.id];
      return {
        ...claim,
        // The engine's own answer for this claim, read on the day the claim is
        // judged. It replaces the likelihood the map was written with, and it
        // replaces nothing else: the reader's own number and a venue's price
        // are theirs.
        beliefs: {
          ...claim.beliefs,
          model: computed === undefined ? claim.beliefs.model : filled(computed),
        },
        badges: badges.get(claim.id) ?? [],
        standing: standing.get(claim.id),
        // A chain's multiplied-out likelihood is not on a world, so it stays an
        // absence that says so. Nothing here multiplies one.
        pathProduct: { absence: NO_PATH_PRODUCT },
      };
    }),
    links: world.graph.links.map(toLink),
    versions: world.versions,
    worldsPerVersion: world.worlds,
    seed: world.seed,
    warnings: world.warnings,
    origin: from.origin,
  };
}

/**
 * How far one claim moved, as the engine read it.
 *
 * Every part of it is the engine's own: the two readings, the sign that says
 * which way it went, the share of versions that agreed, and whether the move
 * came from nothing but the observation changing how much each version counts.
 * Nothing here subtracts, compares two numbers, or works anything out.
 *
 * @param row The claim's own row of the engine's difference.
 */
function movement(row: ClaimDiff): Movement | undefined {
  const { before, after, delta, agreement } = row;
  if (before === null || after === null || delta === null) {
    return undefined;
  }
  return {
    from: before,
    to: after,
    // Which way it went is the sign of the engine's own difference. Reading a
    // sign is a comparison against nought, not a subtraction: nothing here works
    // out how far anything moved.
    way: delta < 0 ? "down" : "up",
    by: delta,
    sameDirection:
      agreement === null
        ? {
            absence: noReadingAtAll(
              "Only one of the two worlds holds this claim, so there is no direction for the " +
                "versions of the map to have agreed or disagreed about.",
            ),
          }
        : { reading: agreement },
    // A claim with no causes of its own can move under **This happened** without
    // anything pushing on it: the observation makes the versions of the map in
    // which it was likely count for more, and the average shifts. The engine
    // says when that is the whole story, and the panel prints one sentence when
    // it does. **The browser never works this out for itself** — it is a fact
    // about how the engine read the numbers, and only the engine knows it.
    onlyReweighted: row.moved_only_by_reweighting,
  };
}

/** Turn the engine's difference into what the rail and the tiles read. */
function toDiffView(difference: Diff, claims: readonly ClaimView[]): DiffView {
  const byId = new Map(claims.map((claim) => [claim.id, claim]));

  const changed = new Map<string, ClaimChange>();
  for (const [id, one] of Object.entries(difference.claims)) {
    changed.set(id, {
      state: one.state,
      moved: movement(one),
    });
  }

  // The endings that moved, in the engine's own order, largest rank first.
  // Nothing here sorts, re-ranks or drops a row.
  const ranked: DeltaRow[] = difference.rows.map((row): DeltaRow => {
    const claim = byId.get(row.target);
    return {
      claimId: row.target,
      label: claim?.claim ?? NOT_ON_THIS_MAP,
      kind: claim?.kind ?? "market",
      move: {
        reading: {
          from: row.before,
          to: row.after,
          largestOn: row.at_day,
          way: row.peak_delta < 0 ? "down" : "up",
          by: row.peak_delta,
        },
      },
      rangeWidth: { reading: row.range_width },
      agreement: { reading: row.agreement },
    };
  });

  // An ending the engine left off that list did not move. Silence cannot be
  // told from absence — a reader would not know whether the ending held still
  // or is simply not on this map — so it gets a quiet row of its own, after
  // every ranked row and never mixed in among them.
  const listed = new Set(ranked.map((row) => row.claimId));
  const held: DeltaRow[] = claims
    .filter(
      (claim) =>
        (claim.kind === "market" || claim.kind === "not_tradeable") &&
        !listed.has(claim.id) &&
        changed.get(claim.id)?.state === "unchanged",
    )
    .map((claim) => ({
      claimId: claim.id,
      label: claim.claim,
      kind: claim.kind,
      move: {
        absence: inTheEnginesWords(
          NO_CHANGE,
          `${noChangeReason(changed.get(claim.id)?.moved)} It is listed so that holding still ` +
            `cannot be mistaken for not being here.`,
        ),
      },
      rangeWidth: {
        absence: noReadingAtAll(
          "How firm a number is only says something about a number that moved.",
        ),
      },
      agreement: {
        absence: noReadingAtAll(
          "Whether the versions of the map agreed on a direction only says something about a " +
            "claim that had a direction.",
        ),
      },
      noChange: true,
    }));

  const summary: Known<string> = { reading: difference.summary };
  return { claims: changed, rows: [...ranked, ...held], summary, warnings: difference.warnings };
}

/**
 * The branch in the shape that goes over the wire, or a sentence saying why it
 * cannot go.
 *
 * A branch is only askable about when every edit in it can be written down the
 * way the server writes one. Today one edit cannot: a claim of your own needs
 * the part of this product that drafts a whole claim — its wording, how it is
 * judged, by whom, by when — and that is not connected.
 *
 * @param branch The branch the screen is showing.
 * @throws Error With one plain sentence, when the branch cannot be sent.
 */
function sendable(branch: BranchView): WireBranch {
  if (branch.wire === undefined) {
    throw new Error(
      `The branch "${branch.label}" has an edit this build cannot hand to the engine, so no ` +
        `world was asked for. Adding a claim of your own needs the part of this product that ` +
        `drafts one, and that is not connected yet.`,
    );
  }
  return branch.wire;
}

/**
 * Calls the engine for a computed world, for what an edit moved, and for the
 * number on one arrow.
 *
 * It keeps one thing between calls: the stored example itself, because a map is
 * written by hand and does not change while the page is open. It keeps no
 * world, no difference and no likelihood — those are computed results, and a
 * kept one eventually disagrees with the three things it came from.
 */
export class ApiWorldSource implements WorldSource {
  /** The stored examples this page has already read, by their short names. */
  readonly #maps = new Map<string, Promise<FixtureBundle>>();

  /** The base map and its branches, read once and kept for as long as the page is open. */
  async readBundle(id: string): Promise<FixtureBundle> {
    const already = this.#maps.get(id);
    if (already !== undefined) {
      return already;
    }
    const asked = readExample(id);
    this.#maps.set(id, asked);
    try {
      return await asked;
    } catch (failure) {
      // A map that could not be read is not a map we should go on pretending to
      // have. Forgetting it means the next attempt really asks again.
      this.#maps.delete(id);
      throw failure;
    }
  }

  /**
   * One computed world: the map with this branch folded onto it and every
   * likelihood worked through time.
   *
   * @param request Which map, and which branch — sent whole, because there is
   *   nowhere to keep one yet.
   */
  async readWorld(request: WorldRequest): Promise<WorldView> {
    const bundle = await this.readBundle(request.baseId);
    const branch = request.branch;
    const world = await readWorld(
      request.baseId,
      branch === undefined ? null : sendable(branch),
      seedFor(bundle),
    );
    const view = toWorldView(
      world,
      {
        id: bundle.id,
        title: bundle.title,
        day: bundle.fixture_date,
        origin: originOf(world, bundle, branch?.label ?? null),
      },
      branch,
    );
    return branch === undefined ? view : { ...view, branch };
  }

  /**
   * What moved between the map as it was written and the map with this branch
   * folded onto it.
   *
   * @param request Which map and which branch.
   */
  async readDiff(request: DiffRequest): Promise<DiffView> {
    const bundle = await this.readBundle(request.baseId);
    const difference = await readDiff(request.baseId, sendable(request.branch), seedFor(bundle));
    // The claims are needed only for their words and their kinds, so the rail
    // can name an ending rather than print its identifier.
    const claims = bundle.graph.propositions.map(toClaim).concat(request.branch.claims);
    return toDiffView(difference, claims);
  }

  /**
   * The number on one arrow: its target, with its cause **supposed** true.
   *
   * @param request Which map, which branch, and which arrow.
   */
  async readConditional(request: ConditionalRequest): Promise<Known<Ranged>> {
    const bundle = await this.readBundle(request.baseId);
    const answer = await readConditional(
      request.baseId,
      request.branch === undefined ? null : sendable(request.branch),
      seedFor(bundle),
      request.linkId,
    );
    return filled(answer);
  }
}

/**
 * What the canvas draws, written by hand rather than generated.
 *
 * This is the browser's own view of one world — a map with its numbers filled
 * in — and it is deliberately **not** taken from `src/api/schema.ts`. That file
 * is generated from the server's description of itself, and the routes that
 * serve a computed world are being written at the same time as this canvas. If
 * the canvas typed itself against those routes it could not be built until they
 * existed, and it would have to be rewritten every time they changed shape.
 *
 * The rule that shapes everything below: **every slot where a likelihood would
 * go is optional.** A number nobody has computed is not a zero and not a blank;
 * it is an absence, and an absence carries the reason it is absent — "no
 * market", "no engine yet", or a dash inviting the reader's own number. That is
 * the whole of the traceability rule as it reaches this layer: nothing on
 * screen may be a number nobody can account for.
 *
 * Nothing in this file, or anywhere under `src/world`, does arithmetic on a
 * likelihood. Numbers arrive from the server and are carried, unchanged and at
 * full precision, to the moment they are printed.
 *
 * **One thing here is taken from the generated description after all, and it is
 * the exception that proves the rule:** a branch, in the shape the server writes
 * one. That shape is not a view of anything — it is what travels back over the
 * wire when a world is asked for — so re-stating it by hand would be writing
 * down the server's own words and waiting for them to drift.
 */

import type { components } from "../api/schema";

/** What a claim is for. Its shape on the canvas carries this, never its colour. */
export type ClaimKind = "hypothesis" | "event" | "market" | "not_tradeable";

/**
 * How a push behaves when its cause goes away. `trigger` is a toppled domino —
 * it stays toppled. `sustain` is an apple on a desk — take the desk away and
 * the apple falls.
 */
export type LinkMode = "trigger" | "sustain";

/** Whose number this is. The three are never averaged into one. */
export type BeliefOwner = "model" | "user" | "market";

/**
 * A likelihood and the range around it, both at full precision.
 *
 * The range says **how sure we are of the number** — not how much the world can
 * move. How much the world can move is already inside `p`. Rounding to two
 * significant figures happens once, at the moment of display, and never here.
 */
export interface Ranged {
  /** How likely the claim is to come out true, from 0 to 1. */
  readonly p: number;
  /** The bottom of the range around `p`. Never above it. */
  readonly lo: number;
  /** The top of the range around `p`. Never below it. */
  readonly hi: number;
}

/**
 * Which of the five absences this is. It is what picks the words.
 *
 * - `no_engine` — nothing has worked this number through the map yet.
 * - `no_market` — no venue quotes this claim.
 * - `not_said` — nobody has given a number. The one dash on screen with a
 *   meaning: the reader's own empty slot, inviting a number.
 * - `refused` — the engine was asked and **would not** work this number out. It
 *   is its own kind rather than a shade of `no_engine`, because the two are
 *   different facts: *nothing has run yet* invites waiting, and *the engine
 *   turned this down, here is why* invites repairing the thing it turned down.
 *   Reusing one word for both would make the reason on screen the only thing
 *   telling them apart, and a reason is not something code can read back.
 * - `ask_failed` — the engine was asked and one attempt did not come back. It is
 *   the only absence that is not a fact about the map, so it is the only one
 *   that is never kept: ask again and it may well be gone.
 *
 * **The last two are not the same and must not be merged.** A refusal is an
 * answer — the engine looked and said no, and said why — and it will say the
 * same thing every time until the thing it refused is repaired. A failed ask is
 * not an answer at all.
 */
export type AbsenceKind = "no_engine" | "no_market" | "not_said" | "refused" | "ask_failed";

/**
 * A number that is not here, and why.
 *
 * `words` is what the reader sees where the number would have been — "no
 * market", "no engine yet", "not worked out", or a dash. `reason` is the sentence
 * that says why, so no slot on screen is ever merely empty. `kind` is which of
 * the five this is, so that code can tell one absence from another without
 * reading its words back — the dash that invites a number is not the dash that
 * means nothing was computed, and neither of those is a refusal or an ask that
 * did not come back.
 */
/**
 * The mark that says an absence came from the one place absences are made.
 *
 * **It exists only for the compiler.** It is declared and never defined, so
 * nothing is on the object at run time and nothing is carried over a wire — and
 * a hand-built `{ kind, words, reason }` does not compile anywhere but
 * `world/absence.ts`, which is the one module allowed to promise it. The
 * vocabulary says *"these are the words; change them here first"*, and that
 * instruction means nothing while a seventh spelling is one object literal away
 * — as six files proved by holding one each.
 */
declare const WRITTEN_HERE: unique symbol;

export interface Absence {
  /** Which absence this is. */
  readonly kind: AbsenceKind;
  /** What is printed where the number would be. Never blank, never a zero. */
  readonly words: string;
  /** Why there is no number, in plain words. */
  readonly reason: string;
  /** Made by `absence()` or `noReadingAtAll()`, and by nothing else. */
  readonly [WRITTEN_HERE]: true;
}

/**
 * A value we may not have, with the reason standing in its place when we do not.
 *
 * `reading` is optional — every number slot in this view model is — and when it
 * is missing, `absence` is present and says why. The two halves are written as
 * a choice between two shapes so that the type itself forbids an empty slot
 * with no reason attached: there is no way to write one down.
 */
export type Known<T> =
  | { readonly reading: T; readonly absence?: undefined }
  | { readonly reading?: undefined; readonly absence: Absence };

/** The three voices on one claim, each in its own slot, never merged. */
export interface BeliefSlots {
  /** What the model thinks. */
  readonly model: Known<Ranged>;
  /** What the reader thinks. Absent until they say. */
  readonly user: Known<Ranged>;
  /** What a venue is pricing. Absent when no venue quotes this claim. */
  readonly market: Known<Ranged>;
}

/**
 * What kind of push an arrow carries over time.
 *
 * `impulse` is a one-time spike that fades away by its own half-life. `step`
 * switches on and holds. `ramp` climbs from nothing to full size across the
 * delay and then holds. The wire's stroke pattern says which, and it is the
 * only thing the stroke says.
 */
export type LinkShape = "impulse" | "step" | "ramp";

/**
 * Where an arrow and its number came from — a receipt our own pipeline writes,
 * never something a model says about itself.
 *
 * Seven values, drawn on the map as a mark of one, two or three dots at the
 * arrow's tail, with the exact word beside the same mark in the panel.
 */
export type Provenance =
  | "documented"
  | "historical"
  | "market_implied"
  | "argued"
  | "user"
  | "asserted"
  | "simulated";

/** One published item behind an arrow, and the day we fetched it — or that nobody did. */
export interface SourceView {
  /** Where the reader goes to check it. */
  readonly url: string;
  /** What the reader will see when they get there, in the publisher's words. */
  readonly title: string;
  /** The host name the address points at, with any leading `www.` dropped. */
  readonly host: string;
  /** The day our own retrieval step fetched it, or the reason there is no day. */
  readonly retrieved: { readonly day: string } | { readonly absence: Absence };
}

/** How often this kind of thing has happened before, when there is an honest set to count. */
export interface BaseRateView {
  /** The set of past cases being counted, stated so somebody else could recount them. */
  readonly referenceClass: string;
  /** How many cases in that set came out true. */
  readonly k: number;
  /** How many cases are in the set altogether. */
  readonly n: number;
  /** Web addresses where the count can be checked. Empty means nobody has checked it. */
  readonly sources: readonly SourceView[];
}

/** One published item for or against a claim, as the tile shows it. */
export interface EvidenceClipping {
  /** What the source says, in one sentence, in our words. */
  readonly line: string;
  /**
   * A single letter standing for the publication, taken from the host name in
   * the source's own web address — `bbc.com` gives `B`.
   *
   * A letter rather than the publication's icon, on purpose: fetching an icon
   * is a request to somebody else's server, and the packaged demo draws its
   * first frame without making one.
   */
  readonly monogram: string;
  /** The host name the monogram came from, so the letter can be accounted for. */
  readonly host: string;
  /** `1` when the item supports the claim, `-1` when it cuts against it. */
  readonly direction: 1 | -1;
  /** Where to read it, so the reader can check us. */
  readonly url: string;
}

/**
 * A word shown where a likelihood would go.
 *
 * While the reader has supposed a claim true it is true in every simulated
 * world, so there is no number to show and inventing one would answer a
 * question nobody asked. The tile shows *Supposed · Oct 1* instead. Nothing in
 * this pull request produces one — the buttons that do arrive later — but the
 * chip can already render it, and its test proves it.
 */
export interface Standing {
  /** The words, such as "Supposed · Oct 1". */
  readonly words: string;
  /** Why the claim stands this way, for the reader who asks. */
  readonly reason: string;
}

/** One claim, as a tile draws it. */
export interface ClaimView {
  /** The claim's identifier on the map. */
  readonly id: string;
  /** The claim in one sentence, as a person would say it out loud. */
  readonly claim: string;
  /** What this claim is for. Carried on the tile by its shape. */
  readonly kind: ClaimKind;
  /** The day the claim is settled by, as the server wrote it: `2026-11-01`. */
  readonly resolvesBy: string;
  /** Who or what applies the test that settles it. */
  readonly resolutionSource: string;
  /**
   * The test itself, written so that two people reading it would agree on the
   * answer. Too long for a tile; the panel beside the map prints it in full.
   */
  readonly resolutionCriteria: string;
  /**
   * The model's likelihood for this claim before its causes are taken into
   * account. Never drawn on a tile — a second number beside the model's would
   * be a fourth voice — and always drawn in the panel, where the decomposition
   * starts from it.
   */
  readonly prior: Ranged;
  /** How often this kind of thing has happened before, or the reason there is no such count. */
  readonly baseRate: { readonly reading: BaseRateView } | { readonly absence: Absence };
  /** The three likelihoods, side by side. */
  readonly beliefs: BeliefSlots;
  /** At most two published items, for and against. What the tile has room for. */
  readonly evidence: readonly EvidenceClipping[];
  /**
   * Every published item on this claim, in the order the map stores them.
   *
   * The tile shows two; the panel shows all of them, because a claim you can
   * only see half the evidence for is a claim you cannot argue with.
   */
  readonly evidenceInFull: readonly EvidenceClipping[];
  /**
   * The multiplied-out likelihood of the steps of one route from the
   * hypothesis to this claim.
   *
   * A chain of four plausible steps is not a plausible chain, and this is the
   * number that says so. It arrives **on the world**, computed by the engine.
   * Nothing in the browser multiplies anything to fill it in, and the slot holds
   * its absence until the engine can answer.
   */
  readonly pathProduct: Known<Ranged>;
  /** A word shown instead of a likelihood, when the claim is standing on the reader's say-so. */
  readonly standing?: Standing;
  /**
   * What an edit did to this claim, in one word. Absent on a world with no
   * edits behind it — the base map, where nothing has been changed.
   */
  readonly diff?: DiffState;
  /**
   * How far this claim's likelihood moved, when the engine says it moved.
   *
   * Both numbers are the engine's, read on this claim's own resolve-by day, and
   * the browser subtracts nothing: which way it went is the engine's own word.
   * Absent on every claim the engine did not call `shifted`.
   */
  readonly moved?: Movement;
  /**
   * What this claim's tile says about the edits behind it, in order.
   *
   * Two badges in a row read as a sequence: *Supposed · Oct 1* then *Retracted
   * · Oct 2 · by "…"*. Empty on a claim no edit touched.
   */
  readonly badges?: readonly Badge[];
  /**
   * True when this claim is **not** in the world you are looking at.
   *
   * Two worlds are laid out once, together, and painted twice in the same
   * coordinates. A claim that only one of them has is still drawn in the other,
   * faint and dashed, so that flipping between them moves nothing and every
   * difference you see is a real difference rather than a re-layout.
   */
  readonly ghost?: boolean;
}

/**
 * How far a claim's likelihood moved between two worlds, as the engine read it.
 *
 * Both numbers arrive from the engine at full precision and are printed as they
 * came. Which way it went is a word the engine's own reading decides, never a
 * subtraction done here — this half of the product does no arithmetic on the
 * map's numbers, and "is the second bigger than the first" would be the first
 * step down that road.
 */
export interface Movement {
  /** The first world's likelihood, on the claim's own resolve-by day. */
  readonly from: number;
  /** The second world's likelihood, on the same day. */
  readonly to: number;
  /** Which way it went. */
  readonly way: "up" | "down";
  /**
   * How far it moved, as the engine reported it.
   *
   * Carried beside the two readings because a move can be smaller than the
   * second significant figure: when the before and the after print the same,
   * this is the only thing that says anything moved at all.
   */
  readonly by: number;
  /**
   * The share of versions of the map that moved the same way. On screen this is
   * headed **same direction**; the word *agreement* is kept off the screen.
   */
  readonly sameDirection: Known<number>;
  /**
   * True when the engine says this claim moved **only** because an observation
   * made some versions of the map count for more than others.
   *
   * It comes from the engine's difference, on the claim's own row, and the
   * browser must never work it out for itself — whether a claim moved for that
   * reason is a fact about how the engine read the numbers, and only the engine
   * knows it. The panel prints one sentence when it is set.
   */
  readonly onlyReweighted?: boolean;
}

/**
 * What an edit did to a claim.
 *
 * Four of the five are worked out from the branch alone, with no arithmetic
 * anywhere: following arrows is walking, not calculating.
 *
 * - `added` — the claim arrives in an **Add a claim** edit.
 * - `killed` — the claim is the target of a **Suppose this is false**. Forced
 *   false, full stop. "No path from the hypothesis reaches this any more" is a
 *   fact about a route, and the panel's path bar reports it in those words.
 * - `downstream` — the claim is in the affected set of at least one edit: a
 *   claim your change **can** move. Drawn live, its model number reading its
 *   absence, because nothing has worked the new number out.
 * - `untouched` — everything else. Identical to the base world, and the map can
 *   say so without hedging, because that is a proven property of an edit.
 * - `shifted` — the number moved, with a before and an after. It needs two
 *   numbers to compare, so only the engine ever produces one, and the browser
 *   copies the word across rather than deciding it.
 *
 * **Which of the two readings wins.** Once the engine has answered, its own word
 * is the authority wherever it has one — `added`, `killed` and `shifted` are
 * the engine's. `downstream` and `untouched` stay the browser's, because they
 * answer a different question: *can* your edit reach this claim, rather than
 * *did* its number move. A claim the edit can reach whose number did not move is
 * `downstream`, and saying `untouched` about it would be telling the reader
 * their change cannot reach something it can.
 */
export type DiffState = "added" | "killed" | "downstream" | "untouched" | "shifted";

/**
 * One thing a tile says about an edit behind it — *Added*, *Supposed · Oct 1*,
 * *Retracted · Oct 2 · by "…"*.
 *
 * The words are copied from the shared vocabulary and never paraphrased, and
 * none of the six operations' code names ever appears in one.
 */
export interface Badge {
  /** The words on the badge. */
  readonly words: string;
  /** What the badge means, for the reader who asks. */
  readonly reason: string;
  /**
   * True when this badge says an earlier one no longer holds, so the tile can
   * draw the pair as a sequence with an arrow between them.
   */
  readonly overrides?: boolean;
  /**
   * True when this badge is how far the number moved — `.40 → .30 ▼` — rather
   * than a word about an edit.
   *
   * It sits with the badges because it is what the edits did to this claim, and
   * because the tile already reserves room for whatever they have to say. It is
   * drawn differently: the two readings in the number face with a chevron
   * between the old and the new.
   */
  readonly movement?: boolean;
}

/** One arrow, as a wire draws it. */
export interface LinkView {
  /** The arrow's identifier: its two ends joined, such as `H->B`. */
  readonly id: string;
  /** The claim the arrow starts at. */
  readonly source: string;
  /** The claim the arrow ends at. */
  readonly target: string;
  /** Whether the push survives its cause going away. */
  readonly mode: LinkMode;
  /**
   * How hard this arrow pushes, signed, at full precision.
   *
   * It is signed **on the claim, not on the world**. The arrow into *Brent
   * settles below $68* is `+1.6` — positive, because it makes that claim come
   * out true more often — and the thing that claim describes is a *falling*
   * price. So a push's sign is not a direction of financial effect, it never
   * takes a direction hue, and it is carried by the printed sign and a word.
   *
   * Nothing on the canvas adds one of these to anything. Choosing a stroke
   * width or a word for it is a comparison against fixed thresholds.
   */
  readonly strength: number;
  /** Days from the cause becoming true to the push reaching full size. */
  readonly lag: number;
  /** What the push does over time. The wire's stroke pattern, and nothing else. */
  readonly shape: LinkShape;
  /** Days for an `impulse` push to fall to half its size. Absent on the other two shapes. */
  readonly halfLife: number | null;
  /** The mechanism in one to three plain sentences: why this cause moves this effect. */
  readonly rationale: string;
  /** What backs the arrow, each with the day it was fetched or the reason there is none. */
  readonly sources: readonly SourceView[];
  /** Where this arrow came from. Drawn as a mark at the tail, spelled out in the panel. */
  readonly provenance: Provenance;
  /**
   * The target's likelihood with this arrow's source supposed true.
   *
   * Not computed here and not carried on the world: it costs a whole extra
   * run of the map per arrow, so the engine works one out only when a wire is
   * asked about. Until then — and always, in this build, because that route
   * does not exist yet — the slot holds its absence and the wire's chip reads
   * the push back in words instead. Never a guessed number.
   */
  readonly conditional: Known<Ranged>;
  /**
   * True when this arrow is a market feeding back on the world. A feedback
   * arrow is the one arrow allowed to close a loop, and it is set aside when
   * the map is sorted into layers — otherwise there would be no left-to-right
   * order to sort it into.
   */
  readonly reflexive: boolean;
  /**
   * What an edit did to this arrow. Absent when no edit touched it.
   *
   * - `added` — an **Add a claim** edit brought it.
   * - `cut` — a supposition cut it: "take this as given, and do not tell me what
   *   caused it". It is still drawn, faint and dashed, because an arrow that
   *   simply vanished would be a change nobody could see.
   * - `retuned` — a **Change this push** edit moved its number.
   */
  readonly change?: "added" | "cut" | "retuned";
  /**
   * True when this arrow is **not** in the world you are looking at. Drawn faint
   * in the same place, so that flipping between the two worlds moves nothing.
   *
   * A ghost arrow is carried by how faint it is and by nothing else. Its stroke
   * is fully spent saying what kind of push it is — dot-dash for a spike that
   * fades, solid for a switch that holds, doubled when the push only lasts while
   * its cause does — and dashing it to say "other world" as well would leave it
   * saying neither clearly.
   */
  readonly ghost?: boolean;
}

/**
 * One world: a map with its numbers as they stand.
 *
 * "As they stand" is doing real work. In this pull request the numbers are the
 * stored example's own, read from the fixture route. When the engine's world
 * route lands they will be computed, and the slots that read as absences today
 * will fill in. Nothing here has to change for that to happen, because nothing
 * false was written.
 */
export interface WorldView {
  /** Which stored example or map this world was built from. */
  readonly baseId: string;
  /** What the map is called on screen. */
  readonly title: string;
  /**
   * The day the map is set on, as the map itself writes it: `2026-10-01`.
   *
   * Every resolve-by date on the map is a span from this day, and an edit the
   * reader makes takes effect on it, so the map reads the same whenever it is
   * opened. The browser's own clock is never consulted: a supposition dated by
   * the reader's time zone would make the same map read differently in two
   * places.
   */
  readonly today: string;
  /**
   * The branch this world has applied, when it has one.
   *
   * Absent on the base world, which is the empty branch. What the branch panel
   * lists, and what every diff state on the claims above was worked out from.
   */
  readonly branch?: BranchView;
  /** The claim the reader started from. */
  readonly hypothesisId: string;
  /** Every claim on the map. */
  readonly claims: readonly ClaimView[];
  /** Every arrow on the map. */
  readonly links: readonly LinkView[];
  /**
   * How many versions of the map the engine ran to produce these numbers.
   *
   * Absent when nothing was computed — which is every world in this build,
   * because the engine's route does not exist yet. It is the one thing that
   * tells a belief chip whether its range was *computed* across many versions
   * of the map or merely *stated* by whoever wrote the number down, and the
   * chip says a different sentence for each. Nothing else reads it.
   */
  readonly versions?: number;
  /**
   * How many worlds ran under each version of the map: how the dice fall.
   *
   * Absent for the same reason `versions` is. It is printed in the sentence
   * under the map, beside the seed, so that a reader can rebuild this world.
   */
  readonly worldsPerVersion?: number;
  /**
   * The one number every random draw behind these likelihoods came from.
   *
   * A world is replayable from three things — the map, the branch and this — so
   * it is carried here and named under the map. Absent on a world nobody
   * computed.
   */
  readonly seed?: number;
  /**
   * Plain sentences the engine wanted the reader to see under the map.
   *
   * The engine writes these itself — for instance when so few worlds survived an
   * observation that the range around the answer stops meaning much. They are
   * printed as they came and never summarised.
   */
  readonly warnings?: readonly string[];

  /**
   * Where these numbers came from, in one sentence a reader can check.
   *
   * It is printed under the map. A world whose numbers cannot say where they
   * came from is exactly the state this product refuses to show.
   */
  readonly origin: string;
}

/**
 * Which world to read: a base map, optionally with a branch folded onto it.
 *
 * The branch is sent **whole**, not by name, because there is nowhere to keep
 * one yet: the browser holds the branch it built and hands it over with every
 * question. That is also what makes an answer reproducible from three things —
 * the map, the branch and the seed.
 */
export interface WorldRequest {
  /** The stored example or map to read. */
  readonly baseId: string;
  /** The branch to fold. Left out, this is the base world — the empty branch. */
  readonly branch?: BranchView;
}

/** Which two worlds to compare: one map, one seed, one branch against the base world. */
export interface DiffRequest {
  /** The stored example or map both worlds are built from. */
  readonly baseId: string;
  /**
   * The branch the second world has and the first does not.
   *
   * The first world is always the base map with nothing done to it, because
   * that is the comparison the screen offers: the map as it was written against
   * the map with your edits.
   */
  readonly branch: BranchView;
}

/** Which arrow's number is wanted, and in which world. */
export interface ConditionalRequest {
  /** The stored example or map. */
  readonly baseId: string;
  /** The branch to fold first. Left out, the map as it was written. */
  readonly branch?: BranchView;
  /** The arrow whose number is wanted. */
  readonly linkId: string;
}

/** What the engine says happened to one claim between two worlds. */
export interface ClaimChange {
  /** The engine's own word for what happened to it. */
  readonly state: "unchanged" | "shifted" | "added" | "killed";
  /** How far it moved, when it moved. */
  readonly moved?: Movement;
}

/**
 * What the engine says moved between two worlds.
 *
 * Every part of it is the engine's. The browser ranks nothing, re-orders
 * nothing and adds nothing up: `rows` is drawn in the order it arrived, and the
 * two columns beside each row are printed as they came.
 */
export interface DiffView {
  /** Every claim either world holds, by identifier, with what happened to it. */
  readonly claims: ReadonlyMap<string, ClaimChange>;
  /** The endings, largest rank first, exactly as the engine ordered them. */
  readonly rows: readonly DeltaRow[];
  /** The one line saying what this edit did to the trades. */
  readonly summary: Known<string>;
  /** Plain sentences either world wanted the reader to see, each said once. */
  readonly warnings: readonly string[];
}

/**
 * One reason a branch could not be folded onto a map.
 *
 * `message` is the sentence the reader reads; `subject` is the identifier of the
 * claim or the arrow at fault, which is what lets the screen point at the right
 * thing and is never shown. `code` is the stable name of the rule that was
 * broken, for the same reason.
 */
export interface Reason {
  /** Which rule was broken, when the server named one. */
  readonly code?: string;
  /** The identifier of the thing at fault, when the server named one. Never shown. */
  readonly subject?: string;
  /** One plain sentence naming the claim or the arrow by its words. */
  readonly message: string;
}

/* ---- Editing the map: branches, and the six operations ------------------- */

/**
 * One arrow an **Add a claim** edit brings with it.
 *
 * Only the two ends, because that is all working out what an edit can reach
 * needs. When the map itself supplied the arrow — as the stored example's own
 * branch does — the whole arrow is on the branch's `links` as well, and that is
 * what gets drawn.
 */
export interface AddedArrow {
  /** The arrow's identifier. */
  readonly id: string;
  /** The claim the arrow starts at. */
  readonly source: string;
  /** The claim the arrow ends at. */
  readonly target: string;
}

/**
 * One edit in a branch.
 *
 * The six operations keep their code names — `do`, `observe`, `insert`,
 * `retune`, `refine`, `believe` — **in code, in the wire format and in the
 * spec, and nowhere on screen.** What the reader sees is the button they
 * pressed and the badge it earns, both copied word for word from the shared
 * vocabulary. `frontend/src/components/BranchPanel.tsx` is the one place those
 * words are written.
 */
export type Edit =
  /** Take this as given, and do not tell me what caused it. */
  | {
      readonly op: "do";
      /** The claim being supposed true or false. */
      readonly target: string;
      /** True to suppose it holds, false to suppose it does not. */
      readonly value: boolean;
      /** The day the supposition takes effect, as the map writes a day. */
      readonly at: string;
    }
  /** This is news — update what came before it too. */
  | {
      readonly op: "observe";
      readonly target: string;
      readonly value: boolean;
      readonly at: string;
    }
  /** A claim and its arrows arrive together. */
  | {
      readonly op: "insert";
      /** The new claim's identifier on the map. */
      readonly claimId: string;
      /** The new claim in its own words, which is what the badge quotes. */
      readonly words: string;
      /** The arrows that attach it. */
      readonly arrows: readonly AddedArrow[];
      /**
       * The whole claim and its arrows, exactly as the engine drafted them.
       *
       * Present when the part of this product that drafts a claim answered, and
       * absent on a branch a stored example shipped with. It is what lets this
       * edit be written the server's way and folded back onto the map: a claim is
       * not its wording, it is the wording plus how it is judged, by whom, by
       * when and what it started from, and a branch carrying only the words
       * cannot be folded at all.
       */
      readonly drafted?: components["schemas"]["Insert"];
    }
  /** One number on one arrow moves. */
  | {
      readonly op: "retune";
      /** The arrow whose push is being changed. */
      readonly link: string;
      /** The new push, signed, on the same scale the arrow carries. */
      readonly strength: number;
      /** What the push was before, so the panel can read the change back. */
      readonly wasStrength: number;
    }
  /** The finer claims add back up to the one they replace. Not built yet. */
  | { readonly op: "refine"; readonly target: string }
  /** The reader's own likelihood, beside the model's and the market's. */
  | { readonly op: "believe"; readonly target: string; readonly belief: Ranged };

/** The four hues a branch may take. Never amber: amber means "the money moves down". */
export type BranchHue = "violet" | "teal" | "rose" | "slate";

/**
 * A named, ordered list of edits over a base map. A branch *is* the edits.
 *
 * It holds no likelihoods and no results. `claims` and `links` are the drawable
 * detail for what an **Add a claim** edit brought with it, when the map
 * supplied a whole claim rather than only its words — the stored example's own
 * branch does; a claim the reader types does not, and is shown in the branch
 * panel rather than drawn as a tile.
 */
export interface BranchView {
  /** This branch's identifier. */
  readonly id: string;
  /** The name the reader reads. */
  readonly label: string;
  /** Which of the four hues its lane and its name chip take. */
  readonly hue: BranchHue;
  /** The edits, in the order they were made. Appended to, never rewritten. */
  readonly edits: readonly Edit[];
  /** Whole claims an edit added, when the map supplied them. */
  readonly claims: readonly ClaimView[];
  /** Whole arrows an edit added, when the map supplied them. */
  readonly links: readonly LinkView[];
  /**
   * This same branch written the way the server writes one, so it can be sent
   * back to be folded onto the map — when it can be.
   *
   * It is carried rather than rebuilt from `edits` for one reason: an **Add a
   * claim** edit brings a whole claim — how it is judged, by whom, by when, what
   * it started from — and the drawable form above keeps only what a tile needs.
   * Rebuilding the server's form from the drawable one would quietly drop the
   * rest, and the map the engine folded would not be the map on screen.
   *
   * **Absent when this branch cannot be written down in full.** Adding a claim
   * of your own needs the part of this product that drafts one, and that is not
   * connected — so a branch holding one cannot be folded, and asking for its
   * world says exactly that rather than sending half of it.
   *
   * Where it is present the two forms are built side by side, from the same
   * source, and hold the same edits in the same order.
   */
  readonly wire?: WireBranch;
}

/**
 * A branch exactly as the server writes one.
 *
 * Taken from the server's own description of itself, because this shape really
 * is the server's: it is what goes back over the wire when a world is asked
 * for, and re-stating it here would let the two drift apart.
 */
export type WireBranch = components["schemas"]["Branch"];

/** One edit as the server writes one. */
export type WireEdit = components["schemas"]["Branch"]["interventions"][number];

/**
 * One ending the edit can reach, as the rail beside the map lists it.
 *
 * Every number on a row is optional, and before the engine answers every one of
 * them is an absence with its reason. **The rail ranks nothing and computes
 * nothing**: when the engine has ordered these rows the browser draws them in
 * that order, and when it has not the browser says so on its own face.
 */
export interface DeltaRow {
  /** The ending's identifier on the map. */
  readonly claimId: string;
  /** The ending in its own words. */
  readonly label: string;
  /** What kind of ending it is, which is what says whether anything trades. */
  readonly kind: ClaimKind;
  /** How far the number moved, and the day it moved furthest. */
  readonly move: Known<{
    readonly from: number;
    readonly to: number;
    readonly largestOn: string;
    readonly way: "up" | "down";
    /** How far it moved on that day, as the engine reported it. */
    readonly by: number;
  }>;
  /** How firm: the width of this world's own range on the claim. */
  readonly rangeWidth: Known<number>;
  /** Same direction: the share of versions of the map that moved the same way. */
  readonly agreement: Known<number>;
  /**
   * True when this row is here only to say the ending did **not** move.
   *
   * The engine lists the endings that moved; an ending missing from that list
   * could mean either "it did not move" or "it is not on this map", and silence
   * cannot be told from absence. So the rail adds a quiet row reading *no
   * change* for every ending the edit can reach that the engine left out, after
   * the ones it ranked and never mixed in among them.
   */
  readonly noChange?: boolean;
}

/**
 * What the panel beside the map is open on, and what the map draws a ring
 * around. One name for one thing: the map, the panel and the keyboard all mean
 * the same shape by it.
 */
export type Selection =
  | { readonly kind: "claim"; readonly id: string }
  | { readonly kind: "wire"; readonly id: string }
  /**
   * The run that produced the map, rather than anything on it.
   *
   * The panel's third subject: not a claim and not an arrow, but the generation
   * itself — what it cost and every proposal it made, accepted or refused. The
   * identifier is the one the engine minted and sent on the run's first event.
   * Nothing on the canvas draws a ring for it, because there is nothing on the
   * canvas that is it.
   */
  | { readonly kind: "generation"; readonly id: string }
  | null;

/**
 * Why the engine reports no change on a claim, in one sentence.
 *
 * **There is one of these sentences in the product and this is it.** The tile's
 * movement line, the rail's greyed row and the panel's *what your edit did* all
 * read it from here. Before this file there were four of them, written apart,
 * and each named a different cause — which is how two of them came to be flatly
 * false about half the claims they appeared on.
 *
 * **What the engine actually says.** A claim comes out `shifted` only when
 * *both* halves of its test pass: the move clears a floor, and the versions of
 * the map agree on which way it went (`spec/multiverse/diff.md`, and
 * `backend/src/katalyst/domain/diff.py` where the two constants live).
 * `unchanged` is the default — it is what a claim gets when *either* half fails,
 * and the engine does not record which. Neither does its answer: the floor and
 * the bar are constants inside the engine and appear nowhere on the wire.
 *
 * **So this sentence names no cause.** It gives the engine's verdict and the
 * engine's own two numbers and stops. Working the cause out here would mean
 * hard-coding the engine's floor and its bar in the browser and re-running the
 * `shifted` test against them — a second engine on the map, disagreeing with the
 * first about which claims held still, with nobody able to say which was right.
 * The one exception is the case the engine *does* name, on its own row: a claim
 * that moved only because an observation changed how much each version counts.
 *
 * If the reader should be told which half failed, the engine is the one that can
 * say it — either by naming the two constants in its answer or by saying on the
 * row which half a claim failed. Until it does, this sentence is the honest one.
 */

import { toShare, toTwoFigures } from "../../components/BeliefChip";
import type { Movement } from "../../world/types";

/** What the line reads where a move would go, when the engine says there was none. */
export const NO_CHANGE = "no change";

/**
 * The sentence behind *no change* on one claim.
 *
 * @param moved What the engine read on this claim: the two numbers, which way
 *   they went, and the share of versions that agreed. Absent when the engine
 *   reported no pair of readings for it at all — which happens only when one of
 *   the two worlds does not hold the claim.
 */
export function noChangeReason(moved: Movement | undefined): string {
  if (moved === undefined) {
    return (
      "The engine compared the two worlds and reports no change on this claim. It gave no pair " +
      "of readings for it, so there is nothing here to put beside the verdict."
    );
  }
  if (moved.onlyReweighted === true) {
    // The one cause the engine states outright, on the claim's own row. Inside
    // every version of the map the number held exactly still; what moved was how
    // much each version counts, which is why no direction was there to agree on.
    return (
      `The engine reports no change on this claim: inside every version of the map its number ` +
      `held still, and what moved was how much each version counts — from ` +
      `${toTwoFigures(moved.from)} to ${toTwoFigures(moved.to)} across the lot of them.`
    );
  }
  const agreed = moved.sameDirection.reading;
  const versions =
    agreed === undefined
      ? ""
      : `, and ${toShare(agreed)} of the versions of the map moved the same way`;
  return (
    `The engine compared the two worlds and reports no change on this claim: it read ` +
    `${toTwoFigures(moved.from)} then ${toTwoFigures(moved.to)}${versions}. A move is reported ` +
    `only when it is far enough and the versions agree on its direction, and this one did not ` +
    `clear both. Which of the two it was is the engine's to say, and it does not say.`
  );
}

/**
 * The rail beside the map: the endings your edit can reach.
 *
 * An **ending** is where an argument turns into a position — a claim that names
 * something you could trade, or one that names why there is nothing to trade.
 * The rail lists the ones this edit can reach and, beside each, three things:
 * how far its number moved, **how firm** that number is, and whether it went the
 * **same direction** whatever numbers the map started from.
 *
 * **The rail ranks nothing.** When the engine has ordered these rows — largest
 * move along the best-backed route first — the rail draws them in that order and
 * says so. When nothing has, it lists them in the order the map stores them and
 * says *that*, because map order is visibly arbitrary while an invented ranking
 * looks like an answer, and a ranking is the one thing the rail exists to tell
 * you.
 *
 * **An ending that did not move still gets a row.** The engine lists the ones
 * that moved; an ending missing from that list could mean either "it held still"
 * or "it is not on this map", and silence cannot be told from absence. So the
 * unmoved ones follow the ranked ones, reading *no change*, never mixed in among
 * them.
 *
 * The two columns are never folded into any ordering. They answer different
 * questions and a trader weighs them separately; folding the width into a rank
 * would sink exactly the claims that most deserve a second look.
 *
 * **The rows are the first thing in it.** The heading is followed by the table
 * and nothing else; the note saying whose order this is reads as a caption and
 * sits under the rows as one, and the one-line summary of what the edit did
 * closes. It was the other way round, and a reader scrolled past seven lines of
 * prose to reach the artefact the rail exists for.
 */

import { useId, useState } from "react";
import { toDay } from "../graph/diff/days";
import type { DeltaRow, Known } from "../world";
import { toMovement, toShare, toSize } from "./BeliefChip";
import "./deltaRail.css";

/** What the rail needs to draw itself. */
export interface DeltaRailProps {
  /** The endings this edit can reach, in whatever order they arrived in. */
  readonly rows: readonly DeltaRow[];
  /**
   * Whether something has put these rows in an order that means something.
   *
   * True once the engine has ranked them. False before that, and the rail says
   * so out loud rather than letting map order be mistaken for a ranking.
   */
  readonly ranked: boolean;
  /** The one line saying what this edit did to the trades, or the reason there is none. */
  readonly summary: Known<string>;
}

/** What each kind of ending is, in a word. */
const KIND_WORDS: Record<string, string> = {
  market: "tradeable",
  not_tradeable: "not tradeable",
  event: "event",
  hypothesis: "hypothesis",
};

/**
 * One cell: the number, or the words standing where it would have been.
 *
 * A cell with no number is a button, because the reason it has no number is a
 * sentence and there is no room for a sentence in a column this narrow. Pressing
 * it prints the sentence under the rail; its accessible name carries the same
 * sentence, so a reader who never sees the rail gets it without pressing
 * anything.
 */
function Cell({
  value,
  onReason,
}: {
  value: Known<string>;
  onReason: (reason: string | null) => void;
}) {
  if (value.reading !== undefined) {
    return <span className="delta-rail__value">{value.reading}</span>;
  }
  const { words, reason } = value.absence;
  return (
    <button
      className="delta-rail__value delta-rail__value--absent"
      type="button"
      aria-label={`${words}. ${reason}`}
      onClick={() => onReason(reason)}
      onFocus={() => onReason(reason)}
      onMouseEnter={() => onReason(reason)}
    >
      {words}
    </button>
  );
}

/**
 * The change itself, as one cell reads it: `.50 ▼ .42`, and the day the two
 * worlds were furthest apart.
 *
 * A row is read on the **day of largest divergence** rather than on the claim's
 * own judging day, because a change that shows up for a fortnight and then
 * unwinds is the thing a trader acts on — so the row names that day.
 */
function changeOf(row: DeltaRow): Known<string> {
  const move = row.move.reading;
  if (move === undefined) {
    return { absence: row.move.absence };
  }
  return { reading: toMovement(move.from, move.to, move.by, move.way) };
}

/**
 * How firm the new number is: the width of its own range.
 *
 * A width is a **size**, not a likelihood: it is how far apart the two ends of a
 * band sit. So it takes no certainty guard — a band four thousandths wide is a
 * remarkably firm number and the reader wants to see it, where `<.01` would say
 * only that it is small.
 */
function firmnessOf(row: DeltaRow): Known<string> {
  return row.rangeWidth.reading === undefined
    ? { absence: row.rangeWidth.absence }
    : { reading: toSize(row.rangeWidth.reading) };
}

/** The share of versions of the map that moved the same way, as a whole percentage. */
function sameDirectionOf(row: DeltaRow): Known<string> {
  return row.agreement.reading === undefined
    ? { absence: row.agreement.absence }
    : { reading: toShare(row.agreement.reading) };
}

/** The rail beside the map. */
export function DeltaRail({ rows, ranked, summary }: DeltaRailProps) {
  const [reason, setReason] = useState<string | null>(null);
  const headingId = useId();

  // The one line saying what the edit did to the trades. The engine writes it
  // from a fixed template with its own numbers in the blanks; before it has, the
  // slot says why there is none. It is written here rather than twice below
  // because it is the same line in both of the rail's two states.
  const theSummary = (
    <p className="delta-rail__summary">
      {summary.reading ?? summary.absence.words}
      {summary.reading === undefined ? (
        <span className="delta-rail__summary-reason">{summary.absence.reason}</span>
      ) : null}
    </p>
  );

  return (
    <section className="delta-rail" aria-labelledby={headingId}>
      <h2 className="delta-rail__heading" id={headingId}>
        Where this edit ends up
      </h2>

      {rows.length === 0 ? (
        <>
          <p className="delta-rail__empty">
            No ending on this map is reachable from your edits yet. Make one — press E on a claim,
            or open a claim in the panel and take up <b>Change this claim</b> — and the endings it
            can reach are listed here.
          </p>
          {theSummary}
        </>
      ) : (
        <>
          {/* **The rows come first, and everything else is written under
              them.** The heading used to be followed by the summary — four or
              five lines at this width — and then by the note saying whose
              order this is, three more. Seven lines of prose stood between a
              reader and the one artefact that answers *what did my edit do,
              ranked*, which is the thing this product is best at and the last
              thing you landed on. The note reads as a caption, so it is one;
              the summary is a sentence about the whole edit, so it closes.
              Nothing about what the rail may honestly say has changed: ranked
              against unranked, the *no change* row and the reason line are all
              exactly as they were. */}
          <div className="delta-rail__table">
            <div className="delta-rail__labels" aria-hidden="true">
              <span>change</span>
              <span>how firm</span>
              <span>same direction</span>
            </div>
            <ul className="delta-rail__rows">
              {rows.map((row, place) => (
                <li
                  className="delta-rail__row"
                  key={row.claimId}
                  data-moved={row.noChange === true ? "no" : "yes"}
                >
                  <p className="delta-rail__label">
                    {/* Where this ending sits in the engine's own order, which is
                        what the rail is for. It was the claim's identifier, and on
                        a generated map that is twenty-six characters nobody reads
                        (`world/naming.ts`). */}
                    <span className="delta-rail__id">{place + 1}</span>
                    {row.label}
                    <span className="delta-rail__kind">{KIND_WORDS[row.kind] ?? row.kind}</span>
                    {row.move.reading === undefined ? null : (
                      <span className="delta-rail__day">
                        {`${row.move.reading.way} · largest on ${toDay(row.move.reading.largestOn)}`}
                      </span>
                    )}
                  </p>
                  <div className="delta-rail__values">
                    <Cell value={changeOf(row)} onReason={setReason} />
                    <Cell value={firmnessOf(row)} onReason={setReason} />
                    <Cell value={sameDirectionOf(row)} onReason={setReason} />
                  </div>
                </li>
              ))}
            </ul>
          </div>

          <p className="delta-rail__order">
            {ranked
              ? "In the order the engine put them in: the size of the move times the weakest arrow on the best-backed route behind it. Endings that did not move follow, and are not ranked."
              : "In map order. Nothing has ranked these, because nothing has worked out a number to rank them by."}
          </p>

          {theSummary}

          <p className="delta-rail__reason">
            {reason ??
              "Every reading above is the engine's own, in the engine's own order. Reach one with " +
                "the keyboard, or point at it, and whatever it has to say is printed here."}
          </p>
        </>
      )}
    </section>
  );
}

