1	/**
2	 * The one end-to-end test: the stored example, opened and edited, **by keyboard
3	 * alone**.
4	 *
5	 * It is the only test in this product that drives a real browser against a real
6	 * server, so it is spent on the one claim nothing else can make: that the two
7	 * halves, started the way a person starts them, draw the stored example — and
8	 * that the three things the interface exists to say are on the screen.
9	 *
10	 * 1. **The map draws, with the engine's own numbers**, from the server's own
11	 *    copy of the example. Nothing on it is typed into the browser — and nothing
12	 *    is typed into this file either: every number below is compared with itself
13	 *    across a change, or checked for its shape, never for its value.
14	 * 2. **Opening the strike branch moves the numbers, and OPEC+'s announcement
15	 *    does not move.** That is the product's central correctness claim — *here is
16	 *    what your edit can reach, and here is what it provably cannot* — and it is
17	 *    checked here against the engine's own answer rather than against a shape a
18	 *    test wrote out. It is also where the browser's structural reading and the
19	 *    engine's meet: the browser is what puts *untouched* on OPEC's announcement,
20	 *    and the engine is what leaves its number where it was.
21	 * 3. **The hypothesis says its supposition was overridden**, word for word:
22	 *    *Supposed · Oct 1 → Retracted · Oct 2 · by "a confirmed military strike on
23	 *    Iranian territory"* — read off the world the engine built.
24	 *
25	 * **The whole walk is done with the keyboard**, and that is not a flourish: it
26	 * is the check that the interface is usable without a mouse end to end. Every
27	 * step below is a keystroke a reader could make.
28	 *
29	 * It needs no model key. The screen it drives is fed by a stored example, which
30	 * calls nothing.
31	 */
32	
33	import { expect, type Page, test } from "@playwright/test";
34	import {
35	  readWhenReady,
36	  standingOn,
37	  standOn,
38	  waitForTheAnswer,
39	  waitForTheBranch,
40	  waitForTheLayout,
41	  whereTheMapCameToRest,
42	} from "./waiting.js";
43	
44	/**
45	 * Every arrow the stored example has, on the glass, by name.
46	 *
47	 * **A causal map is its arrows.** A map that drew every claim and none of the
48	 * arrows between them is the wrong picture of the argument, and a silent one —
49	 * every tile is there, in its place, and nothing says how they are joined. The
50	 * suite met exactly that in the wild. On the stored example the only arrow ever
51	 * checked for was `H->C`, the one an edit is made to, so the other seven could
52	 * have gone without a word.
53	 *
54	 * By name rather than by count, because a map drawing six of the eight is the
55	 * same fault arriving quieter.
56	 *
57	 * @param page The page the map is on.
58	 */
59	async function everyArrowIsDrawn(page: Page): Promise<void> {
60	  const eight = ["B->M1", "B->M2", "B->R", "C->B", "H->B", "H->C", "H->N1", "R->B"];
61	  await expect(page.locator(".react-flow__edge")).toHaveCount(eight.length);
62	  await expect
63	    .poll(() =>
64	      page
65	        .locator(".react-flow__edge")
66	        .evaluateAll((wires) => wires.map((wire) => (wire as HTMLElement).dataset.id).sort()),
67	    )
68	    .toEqual(eight);
69	}
70	
71	/**
72	 * Flip to one of the two maps with the keyboard, the way a reader does.
73	 *
74	 * The press is retried rather than assumed, and what is being retried is the
75	 * keyboard's place: a re-render landing between standing on the map and
76	 * pressing the key takes the keyboard off the map, and a map key pressed off
77	 * the map is *correctly* ignored. It presses only while the wrong map is in
78	 * front, so it can never press twice for one flip and land back where it
79	 * started.
80	 *
81	 * @param page The page the map is on.
82	 * @param side Which of the two maps should be in front afterwards, in the words
83	 *   the map bar uses for it.
84	 */
85	async function flipTo(page: Page, side: "as it was written" | "with your edits"): Promise<void> {
86	  const shown = page.locator(".map-bar__side");
87	  const inFront = async () => ((await shown.textContent()) ?? "").trim();
88	  await expect
89	    .poll(
90	      async () => {
91	        if ((await inFront()) === side) {
92	          return side;
93	        }
94	        await page.locator('.react-flow__node[data-id="H"]').focus();
95	        if ((await standingOn(page)) !== "H") {
96	          return await inFront();
97	        }
98	        await page.keyboard.press("Space");
99	        // A moment for the press to land before it is called lost, so that a
100	        // slow render is never mistaken for a keystroke that went nowhere.
101	        await expect(shown)
102	          .toHaveText(side, { timeout: 2_000 })
103	          .catch(() => undefined);
104	        return await inFront();
105	      },
106	      { timeout: 30_000, message: `the map never flipped to "${side}"` },
107	    )
108	    .toBe(side);
109	}
110	
111	/**
112	 * Wait until the keyboard has landed on one of these claims, and say which.
113	 *
114	 * Moving along a wire changes two things — what the line under the map says and
115	 * where the keyboard is — and they are not written in the same breath. Reading
116	 * the second the moment the first appears is reading one keystroke early.
117	 *
118	 * @param page The page the map is on.
119	 * @param any The claims this step is allowed to land on.
120	 */
121	async function landedOn(page: Page, any: readonly string[]): Promise<string> {
122	  await expect
123	    .poll(() => standingOn(page) as Promise<string>, {
124	      timeout: 15_000,
125	      message: `the keyboard never landed on one of ${any.join(", ")}`,
126	    })
127	    .toMatch(new RegExp(`^(${any.join("|")})$`));
128	  return (await standingOn(page)) as string;
129	}
130	
131	/**
132	 * Press Tab until the keyboard is on the map, and say which claim it landed on.
133	 *
134	 * **The map is one stop in the page's tab order and then its own keys take
135	 * over** — j and k down and up a column, h and l along the wires. That is the
136	 * design rather than a shortfall: eight tiles and twenty-four chips as separate
137	 * tab stops would make Tab the slowest way to cross the map, and the line under
138	 * the map says which keys to use instead from the moment it opens.
139	 */
140	async function tabOntoTheMap(page: Page): Promise<string> {
141	  for (let press = 0; press < 40; press += 1) {
142	    await page.keyboard.press("Tab");
143	    const at = await standingOn(page);
144	    if (at !== undefined) {
145	      return at;
146	    }
147	  }
148	  throw new Error("Tab never reached the map; it is not reachable by keyboard.");
149	}
150	
151	/**
152	 * Point at one arrow and open the six things you can do to it.
153	 *
154	 * **Two ways in, both retried, and the failure says which one got how far.** An
155	 * arrow is a curve: the middle of the box around it is usually a tile, and part
156	 * of the curve itself runs under one, so the spot to point at has to be looked
157	 * for rather than worked out. And the keyboard's way in — stand on the arrow
158	 * and press Enter — needs the standing to have taken, which a rebuild of the
159	 * arrow's element undoes. Either alone left this step failing about once in a
160	 * hundred and sixty runs; what is retried is the asking, and what is waited for
161	 * is the panel naming the arrow.
162	 *
163	 * @param page The page the map is on.
164	 * @param id The arrow, by the identifier it carries on the glass.
165	 */
166	async function openThePanelOnTheArrow(page: Page, id: string): Promise<void> {
167	  const arrow = page.locator(`.react-flow__edge[data-id="${id}"]`);
168	  const panel = page.locator(".intervene");
169	  const tried: string[] = [];
170	  // **The arrow is on the glass, or this fails here and says which arrow.**
171	  // This used to wait the missing arrow out and report what each attempt saw,
172	  // because the map really did lose one under load — a tile whose ports the
173	  // drawing library never measured has no arrows drawn to it. The ports are
174	  // declared rather than measured now, so the waiting is gone: if it ever comes
175	  // back, this is where it says so, by name, in fifteen seconds rather than
176	  // forty-five.
177	  await expect(arrow).toHaveCount(1);
178	
179	  const until = Date.now() + 45_000;
180	  while (Date.now() < until) {
181	    const on = await arrow.evaluate((group, which) => {
182	      const line = group.querySelector("path") as SVGPathElement | null;
183	      const toTheScreen = line?.getScreenCTM();
184	      if (line === null || toTheScreen === null || toTheScreen === undefined) {
185	        return null;
186	      }
187	      const total = line.getTotalLength();
188	      for (let step = 1; step < 40; step += 1) {
189	        const along = line.getPointAtLength((total * step) / 40);
190	        const point = new DOMPoint(along.x, along.y).matrixTransform(toTheScreen);
191	        const under = document.elementFromPoint(point.x, point.y);
192	        if (under?.closest(".react-flow__edge")?.getAttribute("data-id") === which) {
193	          return { x: point.x, y: point.y };
194	        }
195	      }
196	      return null;
197	    }, id);
198	    if (on !== null) {
199	      await page.mouse.click(on.x, on.y);
200	    }
201	    await arrow.focus();
202	    const standingOnIt = await page.evaluate(
203	      () => document.activeElement?.closest<HTMLElement>(".react-flow__edge")?.dataset.id,
204	    );
205	    if (standingOnIt === id) {
206	      await page.keyboard.press("Enter");
207	    }
208	    await page.keyboard.press("e");
209	    // **Which arrow the panel is open on is read off the panel itself**, from
210	    // the identifier it carries for exactly this purpose — never from its
211	    // words. The words name an arrow by the claims at its two ends, in their own
212	    // sentences, because an identifier is never put on the screen; a test that
213	    // matched those words would break the day a claim was reworded, and one that
214	    // matched an identifier in them would be asking the screen to break its rule.
215	    const about = await panel.getAttribute("data-about").catch(() => null);
216	    const said = ((await panel.textContent().catch(() => "")) ?? "").trim();
217	    if (about === id) {
218	      return;
219	    }
220	    tried.push(
221	      `point ${on === null ? "none on the glass" : `${Math.round(on.x)},${Math.round(on.y)}`}` +
222	        ` · keyboard ${standingOnIt ?? "off the map"} · panel on ${about ?? "nothing"} "${said.slice(0, 50)}"`,
223	    );
224	    await page.waitForTimeout(250);
225	  }
226	  throw new Error(
227	    `the panel never opened on ${id}. What each attempt got:\n${tried.slice(-6).join("\n")}`,
228	  );
229	}
230	
231	/**
232	 * Every window this interface is held to.
233	 *
234	 * The whole of it was measured against the first; the other two are the two
235	 * laptop screens a reviewer is most likely to open it on, and every layout
236	 * defect the interface audit found showed up at one of them and not at 1600.
