244	/**
245	 * Every control in the panel beside the map can actually be reached and pressed.
246	 *
247	 * **This is a geometric assertion and never a picture.** A stored screenshot
248	 * over a canvas with a background-threaded layout engine, two variable fonts and
249	 * an arrival animation is a flake generator, and this project has already paid
250	 * for chasing flakes. What it asserts instead is the thing every layout defect
251	 * the interface audit found had in common: something in the panel could be seen
252	 * in the markup and not used on the screen.
253	 *
254	 * **Three questions per control, and the third is the one that bites.**
255	 *
256	 * 1. It is drawn at a size at all.
257	 * 2. Scrolled to, it lies inside the panel's **client box** — the part of the
258	 *    panel that is actually on the glass, inside its border and beside its
259	 *    scrollbar. Scrolled out of view is fine and is why each control is scrolled
260	 *    to first: the panel scrolls as one and marks its edges, so below the fold is
261	 *    reachable.
262	 * 4. **The panel itself does not scroll sideways.** This is a question of its
263	 *    own and not a consequence of the second. The panel scrolls up and down, and
264	 *    a box that scrolls on one axis scrolls on the other as well unless it is
265	 *    told not to — so a field that runs past the right edge makes the panel
266	 *    wider inside than it is on the glass, scrolling to that field slides the
267	 *    whole panel left, and the field is then measured *inside* the client box.
268	 *    The first three questions pass on exactly the defect this helper was
269	 *    written for. Asking the panel how wide its content is cannot be fooled by
270	 *    where it happens to be scrolled to.
271	 * 3. **At its own centre, the topmost thing on the screen is the control** — or
272	 *    something inside it. That is the overlap test, and it is the only one of the
273	 *    three that catches a sibling drawn over a button, which is what "nothing is
274	 *    hidden behind anything" means. An earlier version of this helper asked only
275	 *    where boxes were, and against this stylesheet — one scrolling column whose
276	 *    sections all read `overflow: visible` — no box could ever land outside the
277	 *    content. It could not have failed.
278	 *
279	 * Each control is scrolled to over the wire and then measured in the page, which
280	 * is two round trips each rather than one for the lot. That is the price of
281	 * asking a question about what is *on the glass* rather than about what the
282	 * layout says.
283	 *
284	 * @param page The page the map is on.
285	 */
286	async function everyControlInThePanelIsWhole(page: Page): Promise<void> {
287	  const dock = page.locator(".dock");
288	  await expect(dock).toBeVisible();
289	  const controls = dock.locator("button, a, input");
290	  const many = await controls.count();
291	  expect(many, "the panel beside the map holds no controls at all").toBeGreaterThan(0);
292	
293	  const wrong: string[] = [];
294	  for (let at = 0; at < many; at += 1) {
295	    const control = controls.nth(at);
296	    // Brought onto the glass first, because the question is about what a reader
297	    // can reach and a reader scrolls. The panel is the only thing that moves.
298	    await control.scrollIntoViewIfNeeded();
299	    const verdict = await control.evaluate((element) => {
300	      const panel = element.closest<HTMLElement>(".dock");
301	      if (panel === null) {
302	        return "a control left the panel between being counted and being measured";
303	      }
304	      const name = (element.getAttribute("aria-label") ?? element.textContent ?? "")
305	        .replace(/\s+/g, " ")
306	        .trim()
307	        .slice(0, 60);
308	      const box = element.getBoundingClientRect();
309	      if (box.width === 0 || box.height === 0) {
310	        return `"${name}" is drawn at no size at all`;
311	      }
312	      // The part of the panel that is on the glass: inside its border, and
313	      // beside its scrollbar rather than under it.
314	      const frame = panel.getBoundingClientRect();
315	      const left = frame.left + panel.clientLeft;
316	      const top = frame.top + panel.clientTop;
317	      const right = left + panel.clientWidth;
318	      const bottom = top + panel.clientHeight;
319	      if (
320	        box.left < left - 1 ||
321	        box.right > right + 1 ||
322	        box.top < top - 1 ||
323	        box.bottom > bottom + 1
324	      ) {
325	        return (
326	          `"${name}" is drawn at ${Math.round(box.left)},${Math.round(box.top)} to ` +
327	          `${Math.round(box.right)},${Math.round(box.bottom)}, outside the panel's ` +
328	          `${Math.round(left)},${Math.round(top)} to ${Math.round(right)},${Math.round(bottom)} — ` +
329	          `and it had already been scrolled to`
330	        );
331	      }
332	      // **What is actually on top at its centre.** A pseudo-element with
333	      // `pointer-events: none` — the rules the panel draws at its edges — is
334	      // not an answer to this question and the browser does not give one.
335	      const onTop = document.elementFromPoint(
336	        Math.round(box.left + box.width / 2),
337	        Math.round(box.top + box.height / 2),
338	      );
339	      if (onTop === null || !(onTop === element || element.contains(onTop))) {
340	        const over =
341	          onTop === null
342	            ? "nothing at all"
343	            : `<${onTop.tagName.toLowerCase()} class="${onTop.className}">`;
344	        return `"${name}" has ${over} drawn over its own middle`;
345	      }
346	      return null;
347	    });
348	    if (verdict !== null) {
349	      wrong.push(verdict);
350	    }
351	  }
352	  expect(wrong, "controls in the panel a reader cannot reach").toEqual([]);
353	
354	  // Asked last, and of the panel rather than of any one control: by now every
355	  // control has been scrolled to, so anything that could widen the panel has.
356	  const sideways = await dock.evaluate((panel) => panel.scrollWidth - panel.clientWidth);
357	  expect(
358	    sideways,
359	    "the panel beside the map is wider inside than it is on the glass, so something in it runs past its edge",
360	  ).toBeLessThanOrEqual(1);
361	}
