363	/**
364	 * The page itself does not scroll sideways.
365	 *
366	 * **The one assertion here that varies with the window.** The panel is a fixed
367	 * 336 pixels whatever the screen is, so nothing measured inside it changes
368	 * between 1600 and 1280; the stage beside it takes the rest, and the two of them
369	 * together are what can stop fitting. A page that scrolls sideways is the whole
370	 * screen cut off rather than one control, and it is the defect a narrow window
371	 * produces that a wide one hides.
372	 *
373	 * @param page The page to measure.
374	 */
375	async function theScreenFitsItsWindow(page: Page): Promise<void> {
376	  await expect
377	    .poll(
378	      () =>
379	        page.evaluate(() => {
380	          const page_ = document.documentElement;
381	          return page_.scrollWidth - window.innerWidth;
382	        }),
383	      { timeout: 15_000, message: "the page never stopped scrolling sideways" },
384	    )
385	    .toBeLessThanOrEqual(1);
386	}
