388	/**
389	 * The map read as a list is a list of sentences, not a list of words.
390	 *
391	 * **The defect this catches is a column, not a font.** An outline item is a grid
392	 * row, and a grid row whose text track has collapsed wraps one word to a line —
393	 * which turns a seven-claim map into a tree taller than the window and makes the
394	 * no-picture route, the accessibility story, unusable. A third of the outline's
395	 * own width is nowhere near a sentence and far away from two and a half
396	 * characters, so it catches the collapse without pinning a layout.
397	 *
398	 * @param page The page the outline is on.
399	 */
400	async function everyOutlineItemIsASentenceWide(page: Page): Promise<void> {
401	  await expect
402	    .poll(
403	      () =>
404	        page.evaluate(() => {
405	          const outline = document.querySelector<HTMLElement>(".outline");
406	          if (outline === null) {
407	            return ["the map is not being read as a list"];
408	          }
409	          const room = outline.clientWidth;
410	          if (room === 0) {
411	            // A third of nothing is nothing, and every item would pass.
412	            return ["the map read as a list is drawn at no width at all"];
413	          }
414	          const sentences = outline.querySelectorAll<HTMLElement>(".outline__sentence");
415	          if (sentences.length === 0) {
416	            return ["the map read as a list has no items in it"];
417	          }
418	          const thin: string[] = [];
419	          for (const sentence of sentences) {
420	            const width = sentence.getBoundingClientRect().width;
421	            if (width < room / 3) {
422	              thin.push(
423	                `an item is ${Math.round(width)} wide in an outline of ${Math.round(room)}`,
424	              );
425	            }
426	          }
427	          return thin;
428	        }),
429	      { timeout: 15_000, message: "the outline never settled at a readable width" },
430	    )
431	    .toEqual([]);
432	}
