1126	/**
1127	 * The map keeps its arrows when the browser drops the tiles' size notifications.
1128	 *
1129	 * **This is the browser's own failure mode, made total and deterministic.** A
1130	 * `ResizeObserver` is how the drawing library learns how big a thing is, and
1131	 * when too many observations fall due in one frame the browser abandons the
1132	 * rest — *"a ResizeObserver loop completed with undelivered notifications"* —
1133	 * and an abandoned one is never delivered. #37 met that as tiles that never
1134	 * appeared, and fixed it by telling the library each tile's box outright.
1135	 *
1136	 * **A wire needs more than a box.** It is drawn between two ports — the sockets
1137	 * on a tile's edges — and where a port sits inside a tile used to be measured
1138	 * through the very same notification. So with the tiles' notifications dropped
1139	 * the map drew every claim, in its place, visible — and not one arrow. A causal
1140	 * map is its arrows: what is left is the wrong picture of the argument, and a
1141	 * silent one.
1142	 *
1143	 * **It is per tile, which is why it shows up as one missing arrow rather than
1144	 * an empty map.** Measured, dropping one tile's notifications and keeping every
1145	 * other: deafen the insurance premium and the two arrows that touch it go, and
1146	 * only those; deafen the strait and its three go. An arrow is not drawn when
1147	 * *either* end was never measured. That is the shape the end-to-end suite met
1148	 * in the wild — `H->C` absent from the glass, everything else in place — about
1149	 * once in two hundred runs at six workers on a loaded machine.
1150	 *
1151	 * **Why it passes now, and why nothing is retried to make it pass.** Every
1152	 * tile hands the drawing library its box and its four ports outright, worked
1153	 * out by `graph/ports.ts` and written onto the tile in the same numbers, so
1154	 * both ends of every arrow are known before the page has been measured once.
1155	 * With the tiles deaf, this map is drawn exactly as it is drawn with them
1156	 * hearing — which is the strongest form of the claim, and the reason nothing
1157	 * here waits or asks again.
1158	 *
1159	 * The shim below drops only the tiles' notifications and lets the glass's own
1160	 * through, because the library needs that one to draw anything at all.
1161	 */
1162	test("test_the_arrows_are_drawn_when_the_browser_drops_a_size_notification", async ({ page }) => {
1163	  await page.addInitScript(() => {
1164	    const Real = window.ResizeObserver;
1165	    // Written as a plain function rather than a class on purpose: a private
1166	    // field here is compiled to a helper the page has never heard of.
1167	    function DropsTilesNotifications(given: ResizeObserverCallback) {
1168	      const real = new Real((entries, observer) => {
1169	        const kept = entries.filter((one) => one.target.closest(".react-flow__node") === null);
1170	        if (kept.length > 0) {
1171	          given(kept, observer);
1172	        }
1173	      });
1174	      return {
1175	        observe: (target: Element, options?: ResizeObserverOptions) =>
1176	          real.observe(target, options),
1177	        unobserve: (target: Element) => real.unobserve(target),
1178	        disconnect: () => real.disconnect(),
1179	      };
1180	    }
1181	    window.ResizeObserver = DropsTilesNotifications as unknown as typeof ResizeObserver;
